create function public.commercial_stage_rank(p_stage text) returns integer
language sql immutable security invoker set search_path=public as $$
 select case p_stage when 'new' then 0 when 'contact' then 10 when 'qualified' then 20
 when 'visit_scheduled' then 30 when 'visit_completed' then 40 when 'proposal' then 50
 when 'negotiation' then 60 when 'signed' then 70 else null end;
$$;

create function public.commercial_sync_stage_from_fact() returns trigger
language plpgsql security invoker set search_path=public as $$
declare o public.commercial_opportunities%rowtype; s jsonb; enabled boolean;
 target text; outcome text:='skipped'; why text; latest timestamptz; changed bigint;
begin
 -- Stage-change events created below do not enter this function again.
 if not ((new.entity_type='agenda_events' and new.event_type in
   ('visit_scheduled','visit_confirmed','visit_completed','visit_cancelled','visit_no_show','visit_rescheduled'))
  or (new.entity_type='proposals' and new.event_type='proposal_sent')
  or (new.entity_type='commercial_contracts' and new.event_type in ('contract_signed','contract_cancelled'))) then return new; end if;
 target:=case when new.event_type in ('visit_scheduled','visit_confirmed') then 'visit_scheduled'
  when new.event_type='visit_completed' then 'visit_completed'
  when new.event_type='proposal_sent' then 'proposal'
  when new.event_type='contract_signed' then 'signed' else null end;
 -- NO KEY UPDATE serializes stage writes without upgrading the source's FK key-share lock.
 select * into o from public.commercial_opportunities
  where organization_id=new.organization_id and id=new.opportunity_id for no key update;
 if not found then raise exception 'STAGE_OPPORTUNITY_UNAVAILABLE'; end if;
 select auto_stage_enabled into enabled from public.commercial_settings where organization_id=new.organization_id;
 if not coalesce(enabled,false) then why:='disabled';
 elsif new.confirmation<>'confirmed' then why:='unconfirmed'; outcome:='review';
 elsif auth.uid() is null or new.actor_id is distinct from auth.uid() or not private.can_edit_org(new.organization_id) then
  why:='human_review_required'; outcome:='review';
 elsif new.source<>'database' then why:='unsupported_source'; outcome:='review';
 elsif target is null then why:='cancellation_review'; outcome:='review';
 elsif o.stage in ('lost','nurture','signed') then why:='protected_stage'; outcome:='review';
 elsif new.occurred_at>clock_timestamp() then why:='future_fact'; outcome:='review';
 else
  -- Identifiers are selected only from the fixed entity/type pairs above.
  execute format('select to_jsonb(s) from public.%I s where organization_id=$1 and id=$2 and opportunity_id=$3',new.entity_type)
   into s using new.organization_id,new.entity_id,new.opportunity_id;
  if s is null then why:='source_unavailable'; outcome:='review';
  elsif coalesce(s#>>'{snapshot,auto_detected}','false')='true'
    or coalesce(s#>>'{snapshot,source}','') in ('broker_performance','whatsapp_commercial_intelligence')
    or coalesce(s->>'created_by_kind','') in ('ai','system')
    or coalesce(s#>>'{metadata,source}','')='whatsapp_commercial_intelligence' then
   why:='automated_source_review'; outcome:='review';
  elsif new.entity_type='agenda_events' and (
    coalesce(s->>'visit_kind','') not in ('buyer','remote')
    or coalesce(s->>'event_type','') not in ('visita','apresentacao','reuniao_cliente')
    or (target='visit_scheduled' and (coalesce(s->>'status','')<>'scheduled'
      or coalesce(s->>'visit_outcome','') not in ('','confirmed')
      or nullif(s->>'starts_at','') is null or (s->>'starts_at')::timestamptz<now()))
    or (target='visit_completed' and (coalesce(s->>'visit_outcome','')<>'completed'
      or nullif(s->>'starts_at','') is null or (s->>'starts_at')::timestamptz>now()))
   ) then why:='visit_evidence_incomplete'; outcome:='review';
  elsif new.entity_type='proposals' and (coalesce(s->>'status','')<>'enviada'
    or nullif(s->>'sent_at','') is null or (s->>'sent_at')::timestamptz>clock_timestamp()
    or nullif(s->>'unit_id','') is null) then why:='proposal_evidence_incomplete'; outcome:='review';
  elsif new.entity_type='commercial_contracts' and (not private.is_org_admin(new.organization_id)
    or nullif(s->>'cancelled_at','') is not null or nullif(btrim(s->>'document_reference'),'') is null
    or nullif(s->>'unit_id','') is null or coalesce((s->>'amount')::numeric,0)<=0
    or nullif(s->>'signed_at','') is null or (s->>'signed_at')::timestamptz>now()) then
   why:='contract_evidence_incomplete'; outcome:='review';
  else
   select max(e.occurred_at) into latest from public.commercial_events e
    where e.organization_id=new.organization_id and e.opportunity_id=o.id
      and e.event_type in ('created','stage_changed','reactivated') and e.confirmation='confirmed';
   -- now() is transaction-start time. Waiting for a concurrent fact is not backdating.
   if new.occurred_at<latest and new.occurred_at<new.recorded_at then why:='older_than_stage'; outcome:='review';
   elsif public.commercial_stage_rank(target)<=public.commercial_stage_rank(o.stage) then why:='already_at_or_ahead';
   elsif public.commercial_stage_rank(o.stage) is null then why:='protected_stage'; outcome:='review';
   else
    update public.commercial_opportunities set stage=target
     where organization_id=new.organization_id and id=o.id and stage=o.stage;
    get diagnostics changed=row_count;
    if changed<>1 then raise exception 'STAGE_UPDATE_NOT_CONFIRMED'; end if;
    outcome:='advanced'; why:='documented_fact';
   end if;
  end if;
 end if;
 insert into public.commercial_stage_decisions(organization_id,event_id,opportunity_id,event_type,
 previous_stage,target_stage,resulting_stage,decision,reason,actor_id,occurred_at)
 values(new.organization_id,new.id,o.id,new.event_type,o.stage,target,
  case when outcome='advanced' then target else o.stage end,outcome,why,new.actor_id,new.occurred_at);
 return new;
end; $$;
